/**
 * REST contracts shared by the Axios client and the MSW mock server.
 *
 *   POST /api/matches                      -> 201 MatchRecord (created) | 200 MatchRecord (already stored)
 *   GET  /api/players/:playerId/matches    -> Page<MatchRecord> (newest first)
 *   GET  /api/ranking?sessionDurationSec&spawnIntervalSec&page&pageSize -> RankingPage
 *
 * `matchId` is generated by the client when the match ends and doubles as an
 * idempotency key: re-sending the same match returns the stored record.
 */

export type EndReason = 'time_up' | 'destroyed';

export interface MatchConfigSnapshot {
  sessionDurationSec: number;
  spawnIntervalSec: number;
}

export interface MatchRecord {
  matchId: string;
  playerId: string;
  playerName: string;
  /** ISO-8601 timestamp of the end of the match. */
  playedAt: string;
  score: number;
  /** Effective (unpaused) play time in milliseconds. */
  durationMs: number;
  endReason: EndReason;
  config: MatchConfigSnapshot;
}

export interface PageMeta {
  page: number;
  pageSize: number;
  totalItems: number;
  totalPages: number;
  /** Monotonic data version; lets the client discard stale responses. */
  revision: number;
}

export interface Page<T> extends PageMeta {
  items: T[];
}

export interface RankingEntry {
  rank: number;
  matchId: string;
  playerId: string;
  playerName: string;
  score: number;
  durationMs: number;
  playedAt: string;
}

export interface RankingPage extends Page<RankingEntry> {
  config: MatchConfigSnapshot;
}

export interface ApiErrorBody {
  error: { code: string; message: string };
}

export const DEFAULT_PAGE_SIZE = 5;
export const MAX_PAGE_SIZE = 50;

export const API_ROUTES = {
  matches: '/api/matches',
  playerMatches: (playerId: string) => `/api/players/${encodeURIComponent(playerId)}/matches`,
  ranking: '/api/ranking',
} as const;

/**
 * Deterministic ranking order: higher score, then longer survival, then the
 * earlier achievement, then matchId as a final unique tiebreaker.
 */
export function compareRanking(a: MatchRecord, b: MatchRecord): number {
  return (
    b.score - a.score ||
    b.durationMs - a.durationMs ||
    a.playedAt.localeCompare(b.playedAt) ||
    a.matchId.localeCompare(b.matchId)
  );
}

export function sameConfig(a: MatchConfigSnapshot, b: MatchConfigSnapshot): boolean {
  return a.sessionDurationSec === b.sessionDurationSec && a.spawnIntervalSec === b.spawnIntervalSec;
}

export function isMatchRecord(value: unknown): value is MatchRecord {
  if (typeof value !== 'object' || value === null) return false;
  const v = value as Record<string, unknown>;
  const config = v.config as Record<string, unknown> | undefined;
  return (
    typeof v.matchId === 'string' &&
    v.matchId.length > 0 &&
    typeof v.playerId === 'string' &&
    typeof v.playerName === 'string' &&
    typeof v.playedAt === 'string' &&
    !Number.isNaN(Date.parse(v.playedAt)) &&
    typeof v.score === 'number' &&
    Number.isInteger(v.score) &&
    v.score >= 0 &&
    typeof v.durationMs === 'number' &&
    v.durationMs >= 0 &&
    (v.endReason === 'time_up' || v.endReason === 'destroyed') &&
    typeof config === 'object' &&
    typeof config.sessionDurationSec === 'number' &&
    typeof config.spawnIntervalSec === 'number'
  );
}
